package br.com.admeclesial.interfaces.web.relatorio;
import br.com.admeclesial.application.relatorio.*; import br.com.admeclesial.domain.financeiro.TipoContribuicao; import br.com.admeclesial.infrastructure.persistence.financeiro.CategoriaFinanceiraRepository; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.UUID;
@Controller @RequestMapping("/relatorios/contribuicoes") public class RelatorioContribuicaoWebController { private final RelatorioContribuicaoApplicationService service; private final RelatorioContextoService contexto; private final CategoriaFinanceiraRepository categorias; public RelatorioContribuicaoWebController(RelatorioContribuicaoApplicationService s,RelatorioContextoService c,CategoriaFinanceiraRepository cat){service=s;contexto=c;categorias=cat;}
 @GetMapping public String tela(@RequestParam(defaultValue="contribuicoes") String visao,@RequestParam(required=false) UUID organizacaoUuid,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate dataInicio,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate dataFim,@RequestParam(required=false) TipoContribuicao tipo,@RequestParam(required=false) UUID categoriaUuid,@RequestParam(required=false) String pessoa,@RequestParam(defaultValue="0") int pagina,@RequestParam(defaultValue="25") int tamanho,Model m){m.addAttribute("organizacoes",contexto.organizacoesAutorizadas());m.addAttribute("categorias",categorias.findAllByOrderByNomeAsc());m.addAttribute("tipos",TipoContribuicao.values());m.addAttribute("visao",visao);m.addAttribute("organizacaoUuid",organizacaoUuid);m.addAttribute("dataInicio",dataInicio);m.addAttribute("dataFim",dataFim);m.addAttribute("tipo",tipo);m.addAttribute("categoriaUuid",categoriaUuid);m.addAttribute("pessoa",pessoa);if(organizacaoUuid!=null){var f=new RelatorioContribuicaoFiltro(organizacaoUuid,dataInicio,dataFim,tipo,categoriaUuid,pessoa,pagina,tamanho);if("dizimistas".equals(visao))m.addAttribute("resultadoDizimistas",service.porDizimista(f));else{m.addAttribute("resultado",service.contribuicoes(f));m.addAttribute("resumo",service.resumo(f));}}return "relatorio/contribuicoes";}
}
